  "steps": [
    {
      "id": 1,
      "claim": "An item can be safely reused only if it can be effectively decontaminated or is not a single‑use consumable.",
      "evidence": "Laboratory safety protocols state that reusable glassware is cleaned and sterilized, whereas consumables like filter paper, paper towels, and contaminated chemicals are discarded.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Glassware used to heat liquids is a reusable laboratory item that can be cleaned after use.",
      "evidence": "Standard lab practice: glass beakers, flasks, and test tubes are washed, rinsed, and autoclaved before reuse.",
      "weight": 0.25,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Filter paper used to filter water is a disposable consumable and is not intended for reuse.",
      "evidence": "Filter paper retains particulates and cannot be reliably cleaned for subsequent use.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "Paper towels used to soak up water are single‑use absorbents and become contaminated with the liquid they absorb.",
      "evidence": "Paper towels cannot be effectively decontaminated and are discarded after one use.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Powdered chemicals cleaned from a spill are likely contaminated and their purity cannot be guaranteed.",
      "evidence": "Spill cleanup protocols require disposal of recovered chemicals because they may have mixed with unknown substances.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "Therefore, the only item among the options that can be safely reused after an investigation is the glassware.",
      "evidence": "Combining steps 2‑5 with the criterion from step 1 shows glassware meets the reuse condition while the others do not.",
      "weight": 0.30,
      "depends_on": [2, 3, 4, 5]
    }
  ],
  "answer": "A",
  "confidence": 0.96,
